def transform(grid):
    h, w = len(grid), len(grid[0])

    # Horizontal bands: extend the observed row-color sequence periodically.
    if all(len(set(row)) == 1 for row in grid):
        for p in range(1, h + 1):
            pattern = {}
            valid = True
            for r in range(h):
                color = grid[r][0]
                if color:
                    k = r % p
                    if k in pattern and pattern[k] != color:
                        valid = False
                        break
                    pattern[k] = color
            if valid:
                return [[pattern[r % p] for _ in range(w)] for r in range(h)]

    # Diagonal stripes repeat along either r+c or c-r.
    for key in (lambda r, c: r + c, lambda r, c: c - r):
        for p in range(1, max(h, w) + 1):
            pattern = {}
            valid = True
            for r in range(h):
                for c in range(w):
                    color = grid[r][c]
                    if color:
                        k = key(r, c) % p
                        if k in pattern and pattern[k] != color:
                            valid = False
                            break
                        pattern[k] = color
                if not valid:
                    break
            if valid and len(pattern) > 1:
                return [[pattern[key(r, c) % p] for c in range(w)]
                        for r in range(h)]

    return grid
